// Native launch resources follow the system theme (redesign L5-D3, D3-Q2):
// carbon #101111 with the dark symbol in dark, paper #F2F1E9 (the light
// theme background) with the light symbol (carbon comma, lime comma with a
// carbon outline) in light. Same symbol size and position in both.
//
// Generated by flutter_native_splash from the `flutter_native_splash` block
// of pubspec.yaml; this test guards the generated files, not the tool.
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';
import 'dart:ui' as ui;

import 'package:flutter_test/flutter_test.dart';

const _res = 'android/app/src/main/res';
const _xcassets = 'ios/Runner/Assets.xcassets';
const _paper = 0xFFF2F1E9;
const _carbon = 0xFF101111;
const _bone = 0xFFF2F1E9;
const _lime = 0xFFBAF23A;

class _Png {
  _Png(this.width, this.height, this.rgba);

  final int width;
  final int height;
  final ByteData rgba;

  int pixel(int x, int y) {
    final i = (y * width + x) * 4;
    final r = rgba.getUint8(i);
    final g = rgba.getUint8(i + 1);
    final b = rgba.getUint8(i + 2);
    final a = rgba.getUint8(i + 3);
    return (a << 24) | (r << 16) | (g << 8) | b;
  }

  /// Number of fully opaque pixels of exactly [argb].
  int count(int argb) {
    var n = 0;
    for (var y = 0; y < height; y++) {
      for (var x = 0; x < width; x++) {
        if (pixel(x, y) == argb) n++;
      }
    }
    return n;
  }

  /// Bounding box of the pixels with any alpha, as [left, top, right, bottom].
  List<int> opaqueBounds() {
    var l = width, t = height, r = -1, b = -1;
    for (var y = 0; y < height; y++) {
      for (var x = 0; x < width; x++) {
        if (rgba.getUint8((y * width + x) * 4 + 3) == 0) continue;
        if (x < l) l = x;
        if (x > r) r = x;
        if (y < t) t = y;
        if (y > b) b = y;
      }
    }
    return [l, t, r, b];
  }
}

Future<_Png> _decode(WidgetTester tester, String path) async {
  final png = (await tester.runAsync(() async {
    final codec = await ui.instantiateImageCodec(File(path).readAsBytesSync());
    final frame = await codec.getNextFrame();
    final image = frame.image;
    final data = await image.toByteData(format: ui.ImageByteFormat.rawRgba);
    final result = _Png(image.width, image.height, data!);
    image.dispose();
    return result;
  }))!;
  return png;
}

String _read(String path) => File(path).readAsStringSync();

String? _styleItem(String xml, String name) {
  final match = RegExp(
    '<item name="${RegExp.escape(name)}">([^<]*)</item>',
  ).firstMatch(xml);
  return match?.group(1)?.trim();
}

void main() {
  group('Android 12+ (values-v31 / values-night-v31)', () {
    test('splash background: paper in light, carbon in dark', () {
      final light = _read('$_res/values-v31/styles.xml');
      final dark = _read('$_res/values-night-v31/styles.xml');
      expect(
        _styleItem(light, 'android:windowSplashScreenBackground'),
        '#F2F1E9',
      );
      expect(
        _styleItem(dark, 'android:windowSplashScreenBackground'),
        '#101111',
      );
      expect(
        _styleItem(light, 'android:windowSplashScreenAnimatedIcon'),
        '@drawable/android12splash',
      );
      expect(
        _styleItem(dark, 'android:windowSplashScreenAnimatedIcon'),
        '@drawable/android12splash',
      );
    });

    testWidgets('icon: light symbol in drawable-*, dark in drawable-night-*', (
      tester,
    ) async {
      for (final density in ['mdpi', 'hdpi', 'xhdpi', 'xxhdpi', 'xxxhdpi']) {
        final light = await _decode(
          tester,
          '$_res/drawable-$density/android12splash.png',
        );
        final dark = await _decode(
          tester,
          '$_res/drawable-night-$density/android12splash.png',
        );
        expect([light.width, light.height], [dark.width, dark.height]);
        // Same box: the light symbol is the Flutter light recolour (shapes a
        // little smaller, 1 dp outline on the lime comma), so its edges land
        // within a couple of pixels of the dark ones.
        final lb = light.opaqueBounds();
        final db = dark.opaqueBounds();
        for (var i = 0; i < 4; i++) {
          expect((lb[i] - db[i]).abs(), lessThanOrEqualTo(2), reason: density);
        }
        expect(light.count(_bone), 0, reason: '$density: no bone on paper');
        expect(light.count(_carbon), greaterThan(0), reason: density);
        expect(light.count(_lime), greaterThan(0), reason: density);
        expect(dark.count(_bone), greaterThan(0), reason: density);
        expect(dark.count(_carbon), 0, reason: density);
      }
    });
  });

  group('Android before 12 (launch_background)', () {
    testWidgets('background bitmap: paper in light, carbon in dark', (
      tester,
    ) async {
      for (final dir in ['drawable', 'drawable-v21']) {
        final light = _read('$_res/$dir/launch_background.xml');
        expect(light, contains('@drawable/background'), reason: dir);
        expect(light, contains('@drawable/splash'), reason: dir);
      }
      for (final dir in ['drawable-night', 'drawable-night-v21']) {
        final dark = _read('$_res/$dir/launch_background.xml');
        expect(dark, contains('@drawable/background'), reason: dir);
        expect(dark, contains('@drawable/splash'), reason: dir);
      }
      final light = await _decode(tester, '$_res/drawable/background.png');
      final dark = await _decode(tester, '$_res/drawable-night/background.png');
      expect(light.pixel(0, 0), _paper);
      expect(dark.pixel(0, 0), _carbon);
    });

    testWidgets('symbol: light in drawable-*, dark in drawable-night-*', (
      tester,
    ) async {
      for (final density in ['mdpi', 'hdpi', 'xhdpi', 'xxhdpi', 'xxxhdpi']) {
        final light = await _decode(
          tester,
          '$_res/drawable-$density/splash.png',
        );
        final dark = await _decode(
          tester,
          '$_res/drawable-night-$density/splash.png',
        );
        expect([light.width, light.height], [dark.width, dark.height]);
        expect(light.count(_bone), 0, reason: '$density: no bone on paper');
        expect(light.count(_carbon), greaterThan(0), reason: density);
        expect(dark.count(_bone), greaterThan(0), reason: density);
      }
    });
  });

  group('iOS LaunchScreen (asset catalog by appearance)', () {
    for (final set in ['LaunchBackground', 'LaunchImage']) {
      test('$set has a dark appearance variant', () {
        final json =
            jsonDecode(_read('$_xcassets/$set.imageset/Contents.json'))
                as Map<String, dynamic>;
        final images = (json['images'] as List).cast<Map<String, dynamic>>();
        final dark = images.where((image) {
          final appearances = image['appearances'] as List?;
          return appearances?.any(
                (a) =>
                    (a as Map)['appearance'] == 'luminosity' &&
                    a['value'] == 'dark',
              ) ??
              false;
        }).toList();
        expect(dark, isNotEmpty);
        for (final image in dark.where((i) => i['filename'] != null)) {
          final file = File('$_xcassets/$set.imageset/${image['filename']}');
          expect(file.existsSync(), isTrue, reason: file.path);
        }
      });
    }

    testWidgets('background colours: paper (any), carbon (dark)', (
      tester,
    ) async {
      final light = await _decode(
        tester,
        '$_xcassets/LaunchBackground.imageset/background.png',
      );
      final dark = await _decode(
        tester,
        '$_xcassets/LaunchBackground.imageset/darkbackground.png',
      );
      expect(light.pixel(0, 0), _paper);
      expect(dark.pixel(0, 0), _carbon);
    });
  });
}
